import{at as e,it as t,n,vt as r}from"./chunks/framework.D9OOHiq-.js";var i=JSON.parse(`{"title":"Commands and Permissions","description":"","frontmatter":{},"headers":[],"relativePath":"en/modules/station/commands.md","filePath":"en/modules/station/commands.md","lastUpdated":0}`),a={name:`en/modules/station/commands.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<h1 id="commands-and-permissions" tabindex="-1">Commands and Permissions <a class="header-anchor" href="#commands-and-permissions" aria-label="Permalink to “Commands and Permissions”">​</a></h1><p>EmakiStation registers its commands at runtime instead of declaring a <code>commands:</code> section in <code>paper-plugin.yml</code>, just like every other module in the series</p><p>Your main command is <code>/emakistation</code>, with the aliases <code>/estation</code> and <code>/est</code>. Run it without arguments, or with an unrecognised subcommand, and it prints the help text</p><h2 id="subcommands" tabindex="-1">Subcommands <a class="header-anchor" href="#subcommands" aria-label="Permalink to “Subcommands”">​</a></h2><table tabindex="0"><thead><tr><th>Usage</th><th>Permission</th><th>Description</th></tr></thead><tbody><tr><td><code>/emakistation</code></td><td>none</td><td>Print help</td></tr><tr><td><code>/emakistation help</code></td><td>none</td><td>Same as no arguments; prints help</td></tr><tr><td><code>/emakistation open &lt;station&gt;</code></td><td><code>emakistation.use</code> + that station&#39;s access permission</td><td>Open the station window</td></tr><tr><td><code>/emakistation dismantle &lt;station&gt;</code></td><td><code>emakistation.dismantle</code> + that dismantle station&#39;s access permission</td><td>Open the dismantle window</td></tr><tr><td><code>/emakistation queue</code></td><td><code>emakistation.use</code></td><td>View your own queue</td></tr><tr><td><code>/emakistation claim</code></td><td><code>emakistation.use</code></td><td>Claim pending outputs</td></tr><tr><td><code>/emakistation cancel &lt;station&gt; &lt;index&gt;</code></td><td><code>emakistation.use</code></td><td>Cancel a queue entry; the index starts at 1</td></tr><tr><td><code>/emakistation list [station]</code></td><td><code>emakistation.use</code></td><td>List stations, or the recipes of one station. Console is allowed</td></tr><tr><td><code>/emakistation reload</code></td><td><code>emakistation.reload</code></td><td>Reload configuration, stations, recipes and GUI templates. Console is allowed</td></tr><tr><td><code>/emakistation debug</code></td><td><code>emakistation.debug</code></td><td>Debug switches, with the same arguments as other modules&#39; debug subcommand. Console is allowed</td></tr><tr><td><code>/emakistation admin queue &lt;player&gt;</code></td><td><code>emakistation.admin</code></td><td>Inspect another player&#39;s queue, loading offline data asynchronously. The name must be present in the server cache, otherwise an unknown-player message is returned. Console is allowed</td></tr></tbody></table><p>You run <code>open</code>, <code>dismantle</code>, <code>queue</code>, <code>claim</code> and <code>cancel</code> as a player (the console gets a players-only message); <code>list</code>, <code>reload</code>, <code>debug</code> and <code>admin</code> also work from the console. Tab-completion offers 10 subcommands (<code>help</code>, <code>open</code>, <code>dismantle</code>, <code>queue</code>, <code>claim</code>, <code>cancel</code>, <code>list</code>, <code>reload</code>, <code>debug</code>, <code>admin</code>), and <code>help</code> only prints the help text</p><p>For the second argument, <code>open</code>, <code>cancel</code> and <code>list</code> complete to loaded crafting station ids, while <code>dismantle</code> completes to loaded dismantle station ids. The first-argument list also includes <code>help</code>; <code>debug</code> completions come from CoreLib&#39;s debug subcommand</p><h2 id="permission-nodes" tabindex="-1">Permission Nodes <a class="header-anchor" href="#permission-nodes" aria-label="Permalink to “Permission Nodes”">​</a></h2><p>Here are the permissions declared in <code>paper-plugin.yml</code> and their defaults:</p><table tabindex="0"><thead><tr><th>Permission</th><th>Default</th><th>Purpose</th></tr></thead><tbody><tr><td><code>emakistation.use</code></td><td><code>true</code></td><td>Use the station window and queue-related subcommands</td></tr><tr><td><code>emakistation.purchase</code></td><td><code>true</code></td><td>Buy extra queue slots</td></tr><tr><td><code>emakistation.dismantle</code></td><td><code>true</code></td><td>Use the dismantle window</td></tr><tr><td><code>emakistation.reload</code></td><td><code>op</code></td><td>Reload configuration</td></tr><tr><td><code>emakistation.debug</code></td><td><code>op</code></td><td>Debug switches</td></tr><tr><td><code>emakistation.admin</code></td><td><code>op</code></td><td>Administrative operations</td></tr></tbody></table><p>Note that <code>emakistation.purchase</code> is deliberately <strong>not</strong> placed under <code>emakistation.queue.*</code>: that prefix is already taken by queue length tiers, and mixing the two would make the meanings hard to tell apart. To buy a slot you also need <code>queue.purchase.enabled</code> in <code>config.yml</code> and <code>queue.allow_purchase</code> on the station to both be true</p><h2 id="per-station-access-permissions" tabindex="-1">Per-Station Access Permissions <a class="header-anchor" href="#per-station-access-permissions" aria-label="Permalink to “Per-Station Access Permissions”">​</a></h2><p>Crafting stations and dismantle stations have separate access prefixes. Leave <code>permission</code> empty in the configuration and it falls back to a node derived from the id:</p><table tabindex="0"><thead><tr><th>Type</th><th>Configuration key</th><th>Fallback node when empty</th></tr></thead><tbody><tr><td>Crafting station</td><td><code>permission</code> in <code>stations/&lt;id&gt;.yml</code></td><td><code>emakistation.access.&lt;id&gt;</code></td></tr><tr><td>Dismantle station</td><td><code>permission</code> in <code>stations_dismantle/&lt;id&gt;.yml</code></td><td><code>emakistation.dismantle.access.&lt;id&gt;</code></td></tr></tbody></table><p>You will not find these prefixes declared in the descriptor, because the node names depend on which stations you configure. To grant the example station and the example dismantle station:</p><div class="language-text" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>emakistation.access.blacksmith</span></span>
<span class="line"><span>emakistation.dismantle.access.example_dismantle</span></span></code></pre></div><h2 id="queue-length-permission-tiers" tabindex="-1">Queue Length Permission Tiers <a class="header-anchor" href="#queue-length-permission-tiers" aria-label="Permalink to “Queue Length Permission Tiers”">​</a></h2><p>With <code>queue.permission_tiers</code> enabled, the highest number among your <code>emakistation.queue.&lt;n&gt;</code> nodes wins, and <code>&lt;n&gt;</code> is the queue length. If you have no node under that prefix, <code>base_length</code> stays unchanged</p><div class="language-text" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>emakistation.queue.8</span></span>
<span class="line"><span>emakistation.queue.16</span></span></code></pre></div><p>Holding both of the above yields 16. A permission tier <strong>replaces</strong> the base length, while paid queue slots <strong>stack</strong> on top of the effective tier, and the station&#39;s <code>queue.max_length</code> clamps the result</p><h2 id="threading" tabindex="-1">Threading <a class="header-anchor" href="#threading" aria-label="Permalink to “Threading”">​</a></h2><p>Every subcommand that touches your window or inventory first hops to your own owner thread, because a command can arrive from the console or from another player&#39;s thread. On Folia that is the entity scheduler owner; on Paper it is the main server thread</p>`,22)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};